import logging
import time
from taf.internal.managedobject import ManagedObject
from taf.ul.mobile.ui.android.exceptions import (MessageNotOccur, DisableSimCardFailed,
                                                 EnableSimCardFailed, MenuNotFound, NotFoundSpecifiedNode)
from taf.ul.mobile.ui.android.utils import (get_node_bounds, is_node_in_xml, get_enabled_node_bounds,
                                            get_selected_node_title, get_selected_node_title_in_dialog,
                                            search_nodes_with_resource_id, _get_node_bounds, get_checkedtextview_nodes,
                                            get_selected_checkedtextview_node, get_radio_node_bounds_by_title,
                                            get_widgetswitch_nodes)


class Mobile(ManagedObject):

    def __init__(self, adb_proxy, **kwargs):
        super(Mobile, self).__init__(**kwargs)
        self._adb_proxy = adb_proxy
        self.add_prerequisite(self._adb_proxy)
        self._window_x, self._window_y = None, None

    def _setup(self):
        self._window_x, self._window_y = self._adb_proxy.get_windows_size()

    def disable_sim_card_by_slot_index(self, slot_index, timeout):
        self._adb_proxy.disable_airplane_mode()

        if not self._adb_proxy.is_sim_card_active_for_slot_index(slot_index):
            logging.info("the slot{} sim card is disable".format(slot_index))
            return

        default_sim_slot_index = self._adb_proxy.get_default_mobile_data_slot_index()

        self._tap_sim_card_on_off(slot_index)

        if slot_index == default_sim_slot_index:
            self._confirm_sim_card_switch()

        time.sleep(timeout)

        if self._adb_proxy.is_sim_card_active_for_slot_index(slot_index):
            raise DisableSimCardFailed(slot_index)

    def enable_sim_card_by_slot_index(self, slot_index, timeout):
        self._adb_proxy.disable_airplane_mode()

        default_sim_slot_index = self._adb_proxy.get_default_mobile_data_slot_index()

        if self._adb_proxy.is_sim_card_active_for_slot_index(slot_index):
            logging.info("the slot{} sim card is enable".format(slot_index))
            return

        self._tap_sim_card_on_off(slot_index)

        if slot_index != default_sim_slot_index:
            self._confirm_sim_card_switch()

        time.sleep(timeout)

        if not self._adb_proxy.is_sim_card_active_for_slot_index(slot_index):
            raise EnableSimCardFailed(slot_index)

    def _tap_sim_card_on_off(self, slot_index):
        raise NotImplementedError

    def _confirm_sim_card_switch(self):
        raise NotImplementedError

    def _tap_menu(self, name):
        ui_xml_content = self._adb_proxy.get_ui_xml_content()
        menu_bounds = get_node_bounds(ui_xml_content, name)
        self._tap_menu_by_bounds(menu_bounds)

    def _wipe_to_top(self):
        center_x = int(self._window_x / 2)
        y_percent_20 = int(self._window_y * 0.2)
        y_percent_80 = int(self._window_y * 0.8)
        self._adb_proxy.wipe_screen((center_x, y_percent_20), (center_x, y_percent_80))

    def _wipe_to_bottom_by_step(self):
        center_x = int(self._window_x / 2)
        y_percent_start = int(self._window_y * 0.8)
        y_percent_end = int(self._window_y / 3)
        self._adb_proxy.wipe_screen((center_x, y_percent_start), (center_x, y_percent_end))

    def get_default_mobile_data_slot_index(self):
        return self._adb_proxy.get_default_mobile_data_slot_index()

    def wait_until_message_box(self, message_content, timeout):
        end = time.time() + timeout
        while time.time() < end:
            if message_content in self._adb_proxy.get_ui_xml_content():
                return
        raise MessageNotOccur(message_content)

    def switch_network_mode(self, mode_name, restart_time=30):
        raise NotImplementedError

    def switch_apn(self, apn_name):
        raise NotImplementedError

    def _open_setting(self):
        self._adb_proxy.force_stop_setting()
        time.sleep(1)
        self._adb_proxy.open_setting()
        time.sleep(1)

    def _close_setting(self):
        self._adb_proxy.force_stop_setting()

    def _click_menu(self, menu_title):
        logging.info("click {}".format(menu_title))
        bounds = self._get_menu_bounds(menu_title)
        self._tap_menu_by_bounds(bounds)

    def click_menu_by_resource_id(self, resource_id):
        ui_xml_content = self._adb_proxy.get_ui_xml_content()
        nodes = search_nodes_with_resource_id(ui_xml_content, resource_id)
        if not nodes:
            raise NotFoundSpecifiedNode("resource_id={}".format(resource_id))
        bounds = _get_node_bounds(nodes[0])
        self._tap_menu_by_bounds(bounds)

    def _get_menu_bounds(self, menu_title, timeout=5):
        pre_xml_content = ""
        while timeout:
            ui_xml_content = self._adb_proxy.get_ui_xml_content()
            logging.debug("try to search {} in {}".format(menu_title, ui_xml_content))
            if is_node_in_xml(ui_xml_content, menu_title):
                return get_enabled_node_bounds(ui_xml_content, menu_title)

            if pre_xml_content == ui_xml_content:
                break

            self._wipe_to_bottom_by_step()
            pre_xml_content = ui_xml_content
            timeout -= 1

        raise MenuNotFound("menu {} not find".format(menu_title))

    def _tap_menu_by_bounds(self, bounds):
        center_x = int((bounds[0][0] + bounds[1][0]) / 2)
        center_y = int((bounds[0][1] + bounds[1][1]) / 2)
        self._adb_proxy.tap_by_postion((center_x, center_y))

    def _get_selected_node_title(self):
        ui_xml_content = self._adb_proxy.get_ui_xml_content()
        selected_node_title = get_selected_node_title(ui_xml_content)
        logging.debug("selected {}".format(selected_node_title))
        return selected_node_title

    def _get_selected_node_title_in_dialog(self):
        ui_xml_content = self._adb_proxy.get_ui_xml_content()
        selected_node_title = get_selected_node_title_in_dialog(ui_xml_content)
        logging.debug("selected {}".format(selected_node_title))
        return selected_node_title

    def _open_menu_by_searching_in_settings(self, menu_name):
        self._search_menu_by_specified_name(menu_name)

        bounds = self._get_menu_bounds(menu_name)
        self._tap_menu_by_bounds(bounds)

    def _search_menu_by_specified_name(self, menu_name):
        self._open_setting()
        bounds = self._get_search_menu_bounds()
        self._tap_menu_by_bounds(bounds)

        self._input_text_in_setting_search(menu_name[:-1])

    def _get_search_menu_bounds(self):
        return self._get_menu_bounds("Search")

    def _input_text_in_setting_search(self, search_text):
        for each_chr in search_text:
            if each_chr.isalpha():
                self._adb_proxy.input_text(each_chr)
            elif each_chr.isspace():
                self._adb_proxy.input_space()
            else:
                self._adb_proxy.input_text(r'"\{}"'.format(each_chr))

    def return_to_parentlevel_with_times(self, times):
        for _ in range(times):
            self._adb_proxy.return_to_parentlevel()

    def set_sim_power_off(self, sim_card_name):
        raise NotImplementedError

    def set_sim_power_on(self, sim_card_name):
        raise NotImplementedError

    def start_emergency_call(self, number):
        raise NotImplementedError

    def stop_emergency_call(self):
        raise NotImplementedError

    def get_network_mode(self):
        raise NotImplementedError

    def get_access_point_name(self):
        raise NotImplementedError

    def _get_ui_xml_content(self):
        return self._adb_proxy.get_ui_xml_content()

    def _get_selected_checkedtextview_node_title(self):
        xml_content = self._get_ui_xml_content()
        nodes = get_checkedtextview_nodes(xml_content)
        selected_node = get_selected_checkedtextview_node(nodes)
        if selected_node is None:
            raise NotFoundSpecifiedNode
        return selected_node.get("text")

    def _click_radio_button_by_title(self, title):
        xml_content = self._get_ui_xml_content()
        radio_node_bounds = get_radio_node_bounds_by_title(xml_content, title)
        self._tap_menu_by_bounds(radio_node_bounds)

    def start_debuglogger(self, waiting_time):
        raise NotImplementedError

    def stop_debuglogger(self, waiting_time):
        raise NotImplementedError

    def start_modemlog(self, waiting_time):
        raise NotImplementedError

    def stop_modemlog(self, waiting_time):
        raise NotImplementedError

    def enable_volte_calls(self):
        raise NotImplementedError

    def disable_volte_calls(self):
        raise NotImplementedError

    def _tap_widgetswitch_node(self, node):
        node_bounds = _get_node_bounds(node)
        self._tap_menu_by_bounds(node_bounds)

    def _get_widgetswitch_nodes(self):
        xml_content = self._get_ui_xml_content()
        return get_widgetswitch_nodes(xml_content)

    def _get_widgetswitch_node_text(self, node):
        return node.get("text")

    def unlock_screen(self):
        if self._adb_proxy.is_screen_locked():
            self._adb_proxy.unlock_screen()

    def get_ue_ip(self):
        raise NotImplementedError

    def enable_airplane(self):
        self._adb_proxy.enable_airplane_mode()

    def disable_airplane(self):
        self._adb_proxy.disable_airplane_mode()

    def enable_mobile_data(self):
        self._adb_proxy.enable_mobile_data()

    def disable_mobile_data(self):
        self._adb_proxy.disable_mobile_data()
